import {normalizeReport,normalizeJourney,parseHumanJourney,formatHumanJourney,safeUrl,markdownReport,normalizeDesignSnapshot} from './core.js'; import {normalizeDesignCollection,buildRecreationBrief,recreationMarkdown,recreationAgentRequest,buildReaInvestigationRequest,fullReaAgentRequest} from './recreate.js';
const $=id=>document.getElementById(id), KEY='waypoint.workspace.v2', MAX_REPORTS=50;
function browserUrl(value){const url=safeUrl(value);if(!/^https?:/.test(url))throw new Error('Use an HTTP or HTTPS browser app URL. Native device testing uses the Appium MCP connector.');return url;}
const initial=()=>({project:{name:'Hush',url:'https://hush-frontend-1.onrender.com/sign-in'},reports:[],journeys:[],extensionId:''});
const LOCAL_ORIGIN='http://127.0.0.1:8080';
const localMode=location.origin===LOCAL_ORIGIN;
let localSetup=null,setupError='',checkingConnection=false,runnerAcknowledged=false;
let state=initial(),port=null,session=null,busy=false,recording=false,recordedSteps=[],snapshot=null,bridgeConnected=false,pollTimer=null;
const pending=new Map(),activity=[];let lastWheelAt=0;let findingLimit=100;let agentPaired=false;let counter=0,refreshTimer=null,refreshing=false;let draftAssertions=[];
const node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
function notify(message,error=false){$('notice-text').textContent=String(message);$('notice').className='notice'+(error?' error':'');$('notice').hidden=false;}
$('notice-dismiss').onclick=()=>{$('notice').hidden=true;};
function cleanJourney(raw){if(!raw?.steps?.length)throw new Error('Add at least one test step.');const normalized=normalizeJourney(raw);if(!normalized.url||!/^https?:/.test(normalized.url))throw new Error('Browser journeys need an HTTP or HTTPS app URL. Native device actions use the connected AI agent.');return {...normalized,viewport:{...normalized.viewport,preset:raw.viewport?.preset==='mobile'||normalized.viewport.width===390?'mobile':'desktop'}};}
function save(){try{const safe={...state,reports:state.reports.map(r=>({...r,screenshot:null})),journeys:state.journeys.map(j=>{const {lastRun,...rest}=j;return rest;})};localStorage.setItem(KEY,JSON.stringify(safe));}catch{notify('Browser storage could not save this workspace. Export your reports and journeys before closing.',true);}}
try{const raw=JSON.parse(localStorage.getItem(KEY));if(raw){state={project:{name:String(raw.project?.name||'My app').slice(0,100),url:browserUrl(raw.project?.url||'https://example.com')},reports:Array.isArray(raw.reports)?raw.reports.slice(0,MAX_REPORTS).map(normalizeReport):[],journeys:Array.isArray(raw.journeys)?raw.journeys.slice(0,100).map(cleanJourney):[],extensionId:/^[a-p]{32}$/.test(raw.extensionId)?raw.extensionId:''};}}catch{notify('The saved workspace was unreadable. A fresh workspace is open; you can import exported reports.',true);}
$('extension-id').value=state.extensionId;
function view(name){if(!['overview','live','journeys','findings','recreate','agents','setup','account'].includes(name))name='overview';document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==name);document.querySelectorAll('[data-view]').forEach(b=>{const active=b.dataset.view===name;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('breadcrumb').textContent=({overview:'OVERVIEW',live:'LIVE SESSION',journeys:'TEST JOURNEYS',findings:'FINDINGS',recreate:'RECREATE AN APP',agents:'BRING YOUR AGENT',setup:'CONNECT RUNNER',account:'ACCOUNT & WORKSPACE'})[name];$('page-title').textContent=({overview:'A clearer path to release.',live:'See it. Try it. Test it.',journeys:'Your release routines, repeatable.',findings:'A focused list. A stronger frontend.',recreate:'A reference. An original implementation.',agents:'Test with your own AI agent.',setup:'Connect your browser.',account:'A workspace that remembers.'})[name];if(location.hash!==`#${name}`)history.replaceState(null,'',`#${name}`);}
document.querySelectorAll('[data-view],[data-go]').forEach(b=>b.addEventListener('click',()=>view(b.dataset.view||b.dataset.go)));addEventListener('hashchange',()=>view(location.hash.slice(1)));
function empty(container,title,detail){const box=node('div',undefined,'empty');box.append(node('div','◇','empty-icon'),node('strong',title),node('p',detail));container.append(box);}
function log(text,status='info'){activity.unshift({text:String(text).slice(0,350),status,time:new Date()});if(activity.length>40)activity.pop();renderActivity();}
function renderActivity(){const list=$('activity-log');list.replaceChildren();if(!activity.length){list.append(node('p','Session events will appear here.','caption'));return;}activity.forEach(item=>{const row=node('div',undefined,`activity-item ${item.status}`);row.append(node('span',item.status==='error'?'!':item.status==='success'?'✓':'·','activity-symbol'),node('p',item.text),node('time',item.time.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})));list.append(row);});}
$('clear-activity').onclick=()=>{activity.length=0;renderActivity();};
let designEvidence=[],recreationBrief=null,reaInvestigationRequest=null,designImporting=false;
function invalidateRecreationBrief(){recreationBrief=null;reaInvestigationRequest=null;$('recreate-result').hidden=true;$('recreate-preview').textContent='';$('recreate-agent-request').value='';$('recreate-agent-request').hidden=true;}
function renderRecreate(){
  const permitted=bridgeConnected&&!!session?.consent?.inspect;
  $('recreate-capture').disabled=!permitted||busy||designImporting||designEvidence.length>=12;
  $('recreate-session-status').textContent=permitted?'Authorized inspection ready':'Inspection not connected';
  $('recreate-session-status').className='badge '+(permitted?'confirmed':'review');
  $('recreate-clear').disabled=!designEvidence.length||busy||designImporting;$('recreate-export-snapshots').disabled=!designEvidence.length;
  const list=$('recreate-snapshots');list.replaceChildren();
  if(!designEvidence.length)return empty(list,'Capture your reference screen.','No interface evidence has been collected. You can also import a Waypoint design JSON file.');
  designEvidence.forEach((item,index)=>{const data=item.snapshot,row=node('div',undefined,'recreate-snapshot'),info=node('div');info.append(node('strong',`S${index+1} · ${data.title||new URL(data.origin).hostname}`),node('p',`${data.viewport.width} × ${data.viewport.height} CSS px · ${data.elements.length} elements · ${new Date(data.capturedAt).toLocaleString()}`,'caption'),node('span',item.provenance==='captured'?'Captured by browser runner':'Imported · not independently verified','badge '+(item.provenance==='captured'?'confirmed':'review')));const remove=node('button','Remove','text-button');remove.disabled=busy||designImporting;remove.onclick=()=>{if(busy||designImporting)return;designEvidence.splice(index,1);invalidateRecreationBrief();renderRecreate();};row.append(info,remove);list.append(row);});
}
$('recreate-capture').onclick=async()=>{
  if(busy||designImporting)return;if(!bridgeConnected||!session?.consent?.inspect)return notify('Connect an app tab with inspection permission first.',true);
  if(designEvidence.length>=12)return notify('A recreation brief supports 12 snapshots. Remove or export a snapshot first.',true);
  const capturedSessionId=session.id,capturedOrigin=session.origin;busy=true;renderSession();
  try{const result=await request('designSnapshot');if(!session||session.id!==capturedSessionId||session.origin!==capturedOrigin)throw new Error('The app session changed during inspection. Capture the newly authorized tab.');const data=normalizeDesignSnapshot(result);if(data.origin!==capturedOrigin)throw new Error('The captured interface does not match the authorized app origin.');if(designEvidence.length>=12)throw new Error('A recreation brief supports 12 snapshots. Remove or export a snapshot first.');if(designEvidence.length&&designEvidence[0].snapshot.origin!==data.origin)throw new Error('Clear or export the current evidence before studying a different app.');designEvidence.push({snapshot:data,provenance:'captured'});invalidateRecreationBrief();log(`Interface captured: ${data.elements.length} visible elements. No behavior test was run.`,'success');notify('Visible interface captured in memory. Navigate to another screen to gather more evidence.');}catch(err){notify(err.message,true);}finally{busy=false;renderSession();}
};
$('recreate-import').onchange=async event=>{const file=event.target.files?.[0];if(!file)return;if(busy||designImporting){notify('Wait for the current browser action before importing evidence.',true);event.target.value='';return;}designImporting=true;busy=true;renderSession();try{if(file.size>2000000)throw new Error('Design JSON exceeds the 2 MB limit.');const imported=normalizeDesignCollection(JSON.parse(await file.text()));if(designEvidence.length+imported.length>12)throw new Error('A recreation brief supports up to 12 snapshots.');if(designEvidence.length&&designEvidence[0].snapshot.origin!==imported[0].snapshot.origin)throw new Error('Clear or export the current evidence before importing a different app.');designEvidence.push(...imported);invalidateRecreationBrief();notify(`Imported ${imported.length} design snapshot(s). These supplied records have not been independently verified.`);}catch(err){notify(err.message,true);}finally{event.target.value='';designImporting=false;busy=false;renderSession();}};
$('recreate-clear').onclick=()=>{if(busy||designImporting)return;designEvidence=[];invalidateRecreationBrief();renderRecreate();notify('Design evidence cleared from this workspace memory.');};
$('recreate-export-snapshots').onclick=()=>{if(!designEvidence.length)return;download('waypoint-design-evidence.json',JSON.stringify({schema:'waypoint.design.collection.v1',snapshots:designEvidence.map(item=>item.snapshot)},null,2));};
