$('recreate-form').onsubmit=event=>{event.preventDefault();try{const goal=$('recreate-goal').value,stack=$('recreate-stack').value,projectName=$('recreate-name').value||'My new app',full=$('recreate-mode').value==='full-rea';invalidateRecreationBrief();if(full){reaInvestigationRequest=buildReaInvestigationRequest({goal,stack,projectName,target:$('recreate-target').value});$('recreate-preview').textContent=fullReaAgentRequest(reaInvestigationRequest);$('recreate-result-title').textContent='3. Review your REA investigation request';$('recreate-result-note').textContent='Your agent checks the installed runtime, direct server connection or forwarding grant, live catalog, and target prerequisites. No analysis or tests have started.';$('recreate-result-badge').textContent='REQUEST · NOT AN ANALYSIS';notify('REA investigation request prepared. Paste it into your chosen AI host; no analysis has started.');}else{recreationBrief=buildRecreationBrief({snapshots:designEvidence,goal,stack,projectName});$('recreate-preview').textContent=recreationMarkdown(recreationBrief);$('recreate-result-title').textContent='3. Review your recreation brief';$('recreate-result-note').textContent='Observed interface evidence, inferred build tasks, unverified behavior, and acceptance checks that have not run.';$('recreate-result-badge').textContent='BRIEF · NOT A TEST RESULT';notify('Recreation brief created. Its implementation and acceptance checks have not run.');}$('recreate-agent-request').value=activeRecreationText();$('recreate-result').hidden=false;}catch(err){notify(err.message,true);}};
$('recreate-export-md').onclick=()=>{if(reaInvestigationRequest)download('waypoint-rea-investigation.md',fullReaAgentRequest(reaInvestigationRequest),'text/markdown');else if(recreationBrief)download('waypoint-recreation-brief.md',recreationMarkdown(recreationBrief),'text/markdown');};
