const mutatingCommands=new Set(['click','clickText','type','key','scroll','viewport','recordStart','recordStop','replay']);
function request(command,payload,timeout=25000){return new Promise((resolve,reject)=>{if(!port||!bridgeConnected)return reject(new Error('Connect the Chrome runner first.'));const id=`w-${++counter}-${Date.now()}`,requestSessionId=session?.id;const timer=setTimeout(async()=>{pending.delete(id);if(mutatingCommands.has(command)&&session?.id===requestSessionId&&port&&bridgeConnected){$('live-refresh').checked=false;stopRefresh();log('A browser action timed out. Requesting session stop.','error');try{await request('stop',undefined,10000);if(session?.id===requestSessionId)setSession(null);reject(new Error('The browser action timed out. The app session was stopped; inspect the app directly before continuing. The action may have partially completed.'));}catch{reject(new Error('The browser action timed out and stopping was not acknowledged. End the session in the extension before continuing; the action may have partially completed.'));}}else reject(new Error('The browser runner did not respond in time. Check the app tab and runner, then reconnect if needed.'));},timeout);pending.set(id,{resolve,reject,timer});try{port.postMessage({id,command,payload});}catch(err){clearTimeout(timer);pending.delete(id);reject(new Error('The runner connection closed. Reconnect to continue.'));}});}

function setSession(value){const previous=session?.id;session=value&&typeof value==='object'&&value.origin?value:null;if(previous!==session?.id){snapshot=null;$('live-screenshot').hidden=true;$('screen-empty').hidden=false;$('screen-meta').textContent='Capture on demand';$('click-mode').checked=false;$('scroll-mode').checked=false;recordedSteps=[];draftAssertions=[];$('live-refresh').checked=false;stopRefresh();}recording=!!session?.recording;if(Array.isArray(session?.steps)&&recording)recordedSteps=session.steps.slice(0,100);if(recording&&!pollTimer)pollTimer=setInterval(async()=>{if(!busy&&bridgeConnected)try{const status=await request('status');setSession(status.session);}catch{}},2500);if(!recording&&pollTimer){clearInterval(pollTimer);pollTimer=null;}renderSession();renderRecording();}
function disconnect(reason='Runner disconnected. Your saved reports are still available.'){const old=port;port=null;bridgeConnected=false;runnerAcknowledged=false;agentPaired=false;setSession(null);for(const p of pending.values()){clearTimeout(p.timer);p.reject(new Error('The runner disconnected. Reconnect to continue.'));}pending.clear();if(old)try{old.disconnect();}catch{}renderSession();log(reason,'info');}
$('connect-form').onsubmit=async e=>{e.preventDefault();const id=$('extension-id').value.trim();if(!/^[a-p]{32}$/.test(id))return notify('Use the 32-letter Chrome extension ID (lowercase a–p).',true);if(!window.chrome?.runtime?.connect)return notify('Open this workspace in desktop Chrome. After installing the runner, reload this page to enable the browser connection.',true);disconnect('Starting a new runner connection.');busy=true;renderSession();try{port=chrome.runtime.connect(id,{name:'waypoint-dashboard'});bridgeConnected=true;const connectedPort=port;port.onMessage.addListener(message=>{if(port!==connectedPort)return;if(message?.id&&pending.has(message.id)){const task=pending.get(message.id);pending.delete(message.id);clearTimeout(task.timer);message.ok?task.resolve(message.result):task.reject(new Error(message.error?.message||'The browser action failed.'));return;}if(message?.event==='session'){agentPaired=message.data?.agentPaired===true;setSession(message.data?.session??message.data);}if(message?.event==='activity'){const d=message.data;if(d?.source==='agent')log(`AI agent · ${String(d.command||'Browser action').slice(0,40)} · ${String(d.status||'observed').slice(0,30)}`,d.status==='failed'?'error':d.status==='passed'?'success':'info');}if(message?.event==='recording'){recording=!!message.data?.recording;recordedSteps=Array.isArray(message.data?.steps)?message.data.steps.slice(0,100):recordedSteps;if(session)session.recording=recording;renderSession();renderRecording();}if(message?.event==='telemetry'){const t=message.data;log(`${Number(t?.consoleErrors?.length)||0} console errors · ${Number(t?.networkFailures?.length)||0} request failures observed.`);}});port.onDisconnect.addListener(()=>{if(port!==connectedPort)return;const err=chrome.runtime.lastError;disconnect(err?.message?`Connection ended: ${err.message}`:undefined);});const status=await request('status',undefined,10000);runnerAcknowledged=true;agentPaired=status.agentPaired===true;setSession(status.session);state.extensionId=id;save();notify(session?'Runner connected. Your authorized app tab is ready.':'Runner connected. Open your app tab and authorize it in the extension popup.');log('Chrome runner connected.','success');if(session)view('live');}catch(err){disconnect('Connection failed.');notify(err.message,true);}finally{busy=false;renderSession();}};
$('disconnect').onclick=()=>{disconnect();notify('Workspace disconnected. End the app session in the extension to detach the browser runner.');};
async function action(command,payload,{success='',captureAfter=false,timeout=25000}={}){if(busy)return;busy=true;renderSession();try{const result=await request(command,payload,timeout);if(success)log(success,'success');if(captureAfter&&snapshot&&session?.consent?.screenshot)await captureScreenshot();return result;}catch(err){notify(err.message,true);log(err.message,'error');return null;}finally{busy=false;renderSession();}}
function renderSession(){const active=!!session,inspect=active&&!!session.consent?.inspect,control=active&&!!session.consent?.control,shots=active&&!!session.consent?.screenshot;const connected=bridgeConnected;const label=active?'App connected':connected?'Runner connected':'Runner offline';$('global-connection').replaceChildren(node('i'),document.createTextNode(label));$('global-connection').classList.toggle('connected',active);$('nav-live-dot').classList.toggle('connected',active);$('runner-summary').textContent=active?'Ready':connected?'Waiting':'Offline';$('runner-summary-detail').textContent=active?new URL(session.origin).hostname:connected?'Authorize an app tab':'Connect your local Chrome';$('agent-session-status').textContent=agentPaired?'AI agent paired':'No agent paired';$('agent-session-status').className='badge '+(agentPaired?'confirmed':'review');$('session-title').textContent=active?session.title||'Authorized app tab':'No app session connected';$('session-origin').textContent=active?`${session.origin} · ${session.viewport?.width||'—'} × ${session.viewport?.height||'—'} CSS px`:'Connect the runner, then authorize your app tab.';$('session-indicator').classList.toggle('connected',active);$('connection-detail').textContent=active?`Authorized session: ${session.origin}`:connected?'Runner connected. Authorize your app tab using its extension popup.':'The connection begins only when you click Connect runner.';$('connect-button').disabled=busy;$('disconnect').disabled=!connected||busy;$('stop-session').disabled=!active;$('viewport-preset').disabled=!control||busy;$('viewport-preset').value=session?.viewport?.preset==='mobile'?'mobile':'desktop';$('capture').disabled=!shots||busy;$('run-audit').disabled=!inspect||busy;$('click-mode').disabled=!control||!snapshot||busy;$('scroll-mode').disabled=!control||!snapshot||busy;$('live-refresh').disabled=!shots||busy;['scroll-up','scroll-down'].forEach(id=>$(id).disabled=!control||busy);['live-text','send-text'].forEach(id=>$(id).disabled=!control||busy);document.querySelectorAll('[data-key]').forEach(b=>b.disabled=!control||busy);['assert-text','assert-submit'].forEach(id=>$(id).disabled=!inspect||busy);$('record-toggle').disabled=!control||busy;$('record-toggle').textContent=recording?'■ Stop recording':'● Start recording';$('add-assertion').disabled=!recording||busy||!inspect;$('screen-busy').hidden=!busy||!active;$('screen-hint').textContent=!active?'Screenshots require explicit consent in the extension.':!shots?'Enable screenshots in the extension to capture this tab.':!control?'View only. Enable interaction in the extension to control this tab.':'Scroll over an app region to target its inner container. Refresh updates the captured view.';document.querySelectorAll('[data-replay]').forEach(b=>b.disabled=!control||busy);renderSetupChecks();renderRecreate();}
async function captureScreenshot(){const sessionId=session?.id;const result=await request('screenshot');if(!session||session.id!==sessionId)throw new Error('The app session changed during capture. Capture the newly authorized tab.');if(!result?.dataUrl||!/^data:image\/(png|jpeg);base64,/.test(result.dataUrl))throw new Error('The runner returned an invalid screenshot.');snapshot={...result,capturedAt:Date.now()};$('live-screenshot').src=result.dataUrl;$('live-screenshot').hidden=false;$('screen-empty').hidden=true;$('screen-meta').textContent=`${result.viewport?.width||result.width} × ${result.viewport?.height||result.height} · ${new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'})}`;renderSession();return result;}
$('capture').onclick=async()=>{if(busy)return;busy=true;renderSession();try{await captureScreenshot();log('Screenshot captured. Stored in this session only.','success');}catch(err){notify(err.message,true);log(err.message,'error');}finally{busy=false;renderSession();}};
function screenshotPoint(event){const img=$('live-screenshot');if(!snapshot||!img.naturalWidth||!img.naturalHeight)return null;const rect=img.getBoundingClientRect(),naturalRatio=img.naturalWidth/img.naturalHeight,boxRatio=rect.width/rect.height;let w=rect.width,h=rect.height,left=rect.left,top=rect.top;if(!w||!h)return null;if(boxRatio>naturalRatio){w=h*naturalRatio;left+=(rect.width-w)/2;}else{h=w/naturalRatio;top+=(rect.height-h)/2;}const nx=(event.clientX-left)/w,ny=(event.clientY-top)/h;if(!Number.isFinite(nx)||!Number.isFinite(ny)||nx<0||nx>1||ny<0||ny>1)return null;const width=snapshot.viewport?.width||snapshot.width,height=snapshot.viewport?.height||snapshot.height;if(!(width>0&&height>0))return null;return {x:Math.max(0,Math.min(width-1,Math.round(nx*width))),y:Math.max(0,Math.min(height-1,Math.round(ny*height)))};}
$('live-screenshot').onclick=async e=>{if(!$('click-mode').checked||busy||!session?.consent?.control)return;const point=screenshotPoint(e);if(point)await action('click',point,{success:'Click sent to the authorized app tab.',captureAfter:true});};
$('live-screenshot').addEventListener('wheel',async e=>{if(!$('scroll-mode').checked||!session?.consent?.control||!snapshot||e.ctrlKey||e.metaKey)return;const point=screenshotPoint(e);if(!point)return;e.preventDefault();if(busy||refreshing||Date.now()-lastWheelAt<250)return;const factor=e.deltaMode===1?16:e.deltaMode===2?(snapshot.viewport?.height||snapshot.height):1,limit=value=>Math.max(-700,Math.min(700,Number(value)*factor||0)),deltaY=limit(e.deltaY),deltaX=limit(e.deltaX);if(!deltaY&&!deltaX)return;lastWheelAt=Date.now();await action('scroll',{...point,deltaY,deltaX},{captureAfter:true});},{passive:false});

