$('stop-session').onclick=async()=>{if(!session)return;$('live-refresh').checked=false;stopRefresh();try{await request('stop',undefined,10000);setSession(null);log('App session ended. Browser controls detached.','success');notify('App session ended. You can authorize a new app tab in the extension.');}catch(err){notify(err.message,true);}finally{busy=false;renderSession();}};
$('assert-form').onsubmit=async e=>{e.preventDefault();const text=$('assert-text').value.trim();if(!text)return;const result=await action('assertText',{text});if(!result)return;$('assert-result').hidden=false;$('assert-result').className='assert-result '+(result.passed?'pass':'fail');$('assert-result').textContent=result.detail||(result.passed?'Expected text is visible.':'Expected text was not found.');log(result.passed?'Text assertion passed.':'Text assertion failed.',result.passed?'success':'error');};
$('add-assertion').onclick=()=>{const text=$('assert-text').value.trim();if(!text)return notify('Enter the expected page text first.',true);if(recordedSteps.length+draftAssertions.length>=100)return notify('A journey supports up to 100 steps.',true);draftAssertions.push({type:'assertText',text});renderRecording();log('Assertion queued after the recorded clicks.');};
