$('import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>30000000)throw new Error('Report file exceeds the 30 MB import limit.');const raw=JSON.parse(await file.text()),reports=raw.schema==='waypoint.workspace-reports.v1'?raw.reports:[raw];if(!Array.isArray(reports)||reports.length>MAX_REPORTS)throw new Error('Unsupported report bundle.');const normalized=reports.map(normalizeReport);const existing=new Set(state.reports.map(r=>r.id)),unique=normalized.filter(r=>!existing.has(r.id)&&existing.add(r.id));if(!unique.length)throw new Error('These reports are already imported.');if(state.reports.length+unique.length>MAX_REPORTS)throw new Error('The workspace supports up to 50 reports. Export and remove older reports first.');state.reports.unshift(...unique);save();render();notify(`Imported ${unique.length} report${unique.length===1?'':'s'}.`);}catch(err){notify(err.message,true);}finally{e.target.value='';}};
