function showEvidence(r,f){const c=$('evidence-content');c.replaceChildren();$('evidence-title').textContent=f?f.title:r.target?.kind==='native'?'Native journey evidence':'Page audit evidence';c.append(node('p',`${r.url} · ${r.viewport.width} × ${r.viewport.height} · ${new Date(r.createdAt).toLocaleString()}`,'evidence-meta'));if(f){c.append(node('h4','Observed detail'),node('p',f.detail));if(f.evidence)c.append(node('pre',JSON.stringify(f.evidence,null,2),'evidence-json'));}const checks=node('div',undefined,'evidence-checks');r.checks.forEach(check=>{const row=node('div',undefined,'check-row');row.append(node('span',check.status,'badge '+(check.status==='failed'?'high':check.status==='passed'?'confirmed':'review')),node('div',undefined));row.lastChild.append(node('strong',check.name),node('p',check.detail));checks.append(row);});c.append(checks);if(r.coverage?.note)c.append(node('p',r.coverage.note,'caption'));if(r.screenshot){const img=node('img');img.src=r.screenshot;img.alt='Screenshot attached to this report';c.append(img);}else c.append(node('p','No screenshot is attached to this report. Screenshots require explicit capture and may contain private page content.','caption'));if(snapshot&&session&&r.target?.kind!=='native'&&safeUrl(r.url)===safeUrl(session.url||session.origin)){const attach=node('button','Attach latest captured screenshot','secondary');attach.onclick=()=>{r.screenshot=snapshot.dataUrl;notify('Captured screenshot attached in memory. It may be later than the audit; the capture time is shown below. Export JSON to retain it.');r.screenshotRef=String(snapshot.id||'');r.screenshotCapturedAt=new Date(snapshot.capturedAt).toISOString();showEvidence(r,f);};c.append(attach);}if(r.screenshotCapturedAt||r.screenshotRef?.capturedAt)c.append(node('p',`Screenshot captured at ${new Date(r.screenshotCapturedAt||r.screenshotRef?.capturedAt).toLocaleString()}; audit at ${new Date(r.createdAt).toLocaleString()}.`,'caption'));if(r.telemetry&&r.target?.kind!=='native'){const details=node('details');details.append(node('summary','Browser diagnostics'),node('pre',JSON.stringify(r.telemetry,null,2),'evidence-json'));c.append(details);}const actions=node('div',undefined,'dialog-actions'),exp=node('button',r.screenshot?'Export report with screenshot':'Export this report JSON','dark');exp.onclick=()=>download(`waypoint-report-${r.id.replace(/[^a-zA-Z0-9_-]/g,'').slice(0,40)}.json`,JSON.stringify(r,null,2));const del=node('button','Remove report','text-button danger');del.onclick=()=>{if(confirm('Remove this report from your local workspace? Export it first if you need a copy.')){state.reports=state.reports.filter(x=>x!==r);save();render();$('evidence-dialog').close();}};actions.append(exp,del);c.append(actions);if(!$('evidence-dialog').open)$('evidence-dialog').showModal();}
