function renderSetupChecks(){
  const list=$('setup-checklist');list.replaceChildren();
  const messaging=typeof window.chrome?.runtime?.connect==='function';
  const rows=[];
  if(localMode)rows.push({name:'Local app',ready:!!localSetup,detail:localSetup?`Launcher acknowledged · ${localSetup.version} · Node ${localSetup.nodeVersion}`:setupError||'Checking local launcher…',issue:!!setupError});
  rows.push({name:'Chrome extension interface',ready:messaging,detail:messaging?'Chrome exposes the extension connection interface.':'Open in desktop Chrome, install the runner, then reload this page.'});
  rows.push({name:'Runner connection',ready:runnerAcknowledged,detail:runnerAcknowledged?'The installed runner acknowledged the connection.':'Paste the runner ID below and choose Connect runner.'});
  rows.push({name:'Authorized app tab',ready:!!session,detail:session?session.origin:'Open your app tab, then use the extension popup to authorize it.'});
  rows.push({name:'Page inspection',ready:!!session?.consent?.inspect,detail:session?.consent?.inspect?'Inspection permission is enabled.':'Enable inspection in the app tab’s extension popup to run audits and text checks.'});
  rows.push({name:'Live interaction',ready:!!session?.consent?.control,detail:session?.consent?.control?'Guarded interaction permission is enabled.':'Enable interaction in the app tab’s extension popup to click and replay.'});
  rows.push({name:'Screenshot evidence',ready:!!snapshot,detail:snapshot?`Last screenshot captured at ${new Date(snapshot.capturedAt).toLocaleTimeString()}.`:session?.consent?.screenshot?'Screenshots are allowed. Capture one in Live session to verify it.':'Enable screenshots in the app tab’s extension popup to capture evidence.'});
  rows.forEach(item=>{const row=node('li',undefined,'diagnostic-row'),status=node('span',item.ready?'Ready':item.issue?'Unavailable':'Waiting','badge '+(item.ready?'confirmed':'review')),content=node('div');content.append(node('strong',item.name),node('p',item.detail,'caption'));row.append(status,content);list.append(row);});
  $('check-connection').disabled=busy||checkingConnection;
  $('first-run-card').hidden=runnerAcknowledged;
}
async function loadLocalSetup(){
  if(!localMode)return;
  try{
    const response=await fetch('/api/setup',{cache:'no-store',signal:AbortSignal.timeout(4000)});
    if(!response.ok)throw new Error('The local launcher did not return setup details.');
    const data=await response.json();
    if(data?.mode!=='local'||data.origin!==LOCAL_ORIGIN||typeof data.runnerPath!=='string'||!data.runnerPath||data.runnerPath.length>4096||/[\u0000-\u001f]/.test(data.runnerPath)||typeof data.nodeVersion!=='string'||typeof data.version!=='string')throw new Error('The local launcher returned unsupported setup details.');
    localSetup={runnerPath:data.runnerPath,nodeVersion:data.nodeVersion.slice(0,80),version:data.version.slice(0,80)};
    setupError='';$('local-runner-path').value=localSetup.runnerPath;$('local-runner-install').hidden=false;$('download-runner-install').hidden=true;$('local-practice-app').hidden=false;$('hosted-practice-app').hidden=true;
  }catch(err){localSetup=null;setupError='Launcher unavailable. Restart Waypoint using its included launcher, then check again.';$('local-runner-install').hidden=true;$('download-runner-install').hidden=false;}
  renderSetupChecks();
}
